async function w(t,i=1280,g=.82){if(!t.type.startsWith("image/"))return t;try{const a=await createImageBitmap(t),{width:c,height:o}=a,s=Math.min(1,i/Math.max(c,o,1)),r=Math.max(1,Math.round(c*s)),m=Math.max(1,Math.round(o*s)),e=document.createElement("canvas");e.width=r,e.height=m;const h=e.getContext("2d");if(!h)return a.close(),t;h.drawImage(a,0,0,r,m),a.close();const n=await new Promise(u=>{e.toBlob(d=>u(d),"image/jpeg",g)});if(!n||n.size===0)return t;const p=t.name.replace(/\.[^.]+$/,"")||"image";return new File([n],`${p}.jpg`,{type:"image/jpeg"})}catch{return t}}export{w as compressImageForUpload};
